const agentRaw = $items("AI Agent3")[0].json.output;
const vendor = $items("vendor details1")[0].json;

let items = [];
try {
  const jsonMatch = agentRaw.match(/\[([\s\S]*)\]/);
  items = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  items = [];
}

return items.map(item => ({
  json: {
    vendor_code: vendor.vendor_code,
    vendor_name: vendor.vendor_name,
    vendor_contact: vendor.mobile,
    proposed_rate: item.proposed_rate,
    icode: item.icode
  }
}));
